//#region src/components/markdown/utils/escape-html.ts
const htmlEscapes = {
	"&": "&amp;",
	"<": "&lt;",
	">": "&gt;",
	"\"": "&quot;",
	"'": "&#39;"
};
/**
* Escapes text so it shows up as-is inside HTML, the same way
* marked's default renderers escape code.
*/
const escapeHtml = (text) => text.replace(/[&<>"']/g, (char) => htmlEscapes[char] ?? char);
//#endregion
export { escapeHtml };
